#include "mesh.h"
#include <stdarg.h>
void *resize(void *memory, size_t size) {
    void *result = realloc(memory, size ? size : 1);
    if (!result)
        exit(1);
    return result;
}
char *text(const char *value) {
    char *out = resize(NULL, strlen(value) + 1);
    strcpy(out, value);
    return out;
}
char *format(const char *pattern, ...) {
    va_list args, copy;
    va_start(args, pattern);
    va_copy(copy, args);
    int length = vsnprintf(NULL, 0, pattern, copy);
    va_end(copy);
    char *out = resize(NULL, (size_t)length + 1);
    vsnprintf(out, (size_t)length + 1, pattern, args);
    va_end(args);
    return out;
}
void int_push(IntList *list, int value) {
    if (list->count == list->capacity) {
        list->capacity = list->capacity ? 2 * list->capacity : 8;
        list->data = resize(list->data, (size_t)list->capacity * sizeof(int));
    }
    list->data[list->count++] = value;
}
bool int_contains(const IntList *list, int value) {
    for (int i = 0; i < list->count; ++i)
        if (list->data[i] == value)
            return true;
    return false;
}
IntList int_copy(const IntList *list) {
    IntList out = {0};
    for (int i = 0; i < list->count; ++i)
        int_push(&out, list->data[i]);
    return out;
}
void int_free(IntList *list) {
    free(list->data);
    *list = (IntList){0};
}
static int int_compare(const void *a, const void *b) {
    int x = *(const int *)a, y = *(const int *)b;
    return (x > y) - (x < y);
}
void int_sort(IntList *list) {
    if (list->count > 1)
        qsort(list->data, (size_t)list->count, sizeof(int), int_compare);
}
char *list(const IntList *values, int offset) {
    if (!values->count)
        return text("-");
    char *out = text("");
    for (int i = 0; i < values->count; ++i) {
        char *next = format("%s%s%d", out, i ? " " : "", values->data[i] + offset);
        free(out);
        out = next;
    }
    return out;
}
void line_push(Lines *lines, char *line) {
    if (lines->count == lines->capacity) {
        lines->capacity = lines->capacity ? 2 * lines->capacity : 8;
        lines->data = resize(lines->data, (size_t)lines->capacity * sizeof(char *));
    }
    lines->data[lines->count++] = line;
}
void free_lines(Lines *lines) {
    for (int i = 0; i < lines->count; ++i)
        free(lines->data[i]);
    free(lines->data);
    *lines = (Lines){0};
}
Lines read_lines(const char *path) {
    Lines out = {0};
    FILE *file = fopen(path, "rb");
    if (!file)
        return out;
    char buffer[256];
    while (fgets(buffer, sizeof buffer, file)) {
        size_t length = strlen(buffer);
        if (length && buffer[length - 1] == '\n')
            buffer[--length] = 0;
        line_push(&out, text(buffer));
    }
    fclose(file);
    return out;
}
Lines words(const char *line) {
    Lines out = {0};
    const char *position = line;
    while (*position) {
        while (*position == ' ')
            ++position;
        if (!*position)
            break;
        const char *first = position;
        while (*position && *position != ' ')
            ++position;
        size_t length = (size_t)(position - first);
        char *word = resize(NULL, length + 1);
        memcpy(word, first, length);
        word[length] = 0;
        line_push(&out, word);
    }
    return out;
}
bool integer_word(const char *word) {
    int first = word[0] == '-';
    if (!word[first])
        return false;
    for (int i = first; word[i]; ++i)
        if (word[i] < '0' || word[i] > '9')
            return false;
    return true;
}
Object *read_object(void) {
    Object *out = calloc(1, sizeof(Object));
    char *current = text("default");
    Lines lines = read_lines("input/model.obj");
    for (int i = 0; i < lines.count; ++i) {
        ++out->lines;
        const char *line = lines.data[i];
        if (!*line || *line == '#')
            continue;
        Lines tokens = words(line);
        const char *key = tokens.data[0], *error = NULL;
        if (!strcmp(key, "v")) {
            if (tokens.count != 4 || !integer_word(tokens.data[1]) || !integer_word(tokens.data[2]) ||
                !integer_word(tokens.data[3]))
                error = "bad_vertex";
            else {
                Point point = {{strtoll(tokens.data[1], NULL, 10), strtoll(tokens.data[2], NULL, 10),
                                strtoll(tokens.data[3], NULL, 10)}};
                out->vertices[++out->vertex_count] = point;
            }
        } else if (!strcmp(key, "f")) {
            Polygon polygon = {.line = out->lines};
            if (tokens.count < 4)
                error = "short_face";
            else
                for (int t = 1; t < tokens.count; ++t) {
                    char *vertex = text(tokens.data[t]);
                    char *slash = strchr(vertex, '/');
                    if (slash)
                        *slash = 0;
                    if (!integer_word(vertex) || strtoll(vertex, NULL, 10) == 0) {
                        error = "bad_index";
                        free(vertex);
                        break;
                    }
                    Integer index = strtoll(vertex, NULL, 10),
                            number = index > 0 ? index : out->vertex_count + 1 + index;
                    free(vertex);
                    if (number < 1 || number > out->vertex_count) {
                        error = "out_of_range";
                        break;
                    }
                    int_push(&polygon.vertices, (int)number);
                }
            if (!error) {
                int group = 0;
                while (group < out->groups.count && strcmp(out->groups.data[group], current))
                    ++group;
                if (group == out->groups.count)
                    line_push(&out->groups, text(current));
                polygon.group = group;
                out->polygons[out->polygon_count++] = polygon;
            } else
                int_free(&polygon.vertices);
        } else if (!strcmp(key, "g")) {
            free(current);
            current = text(tokens.count > 1 ? tokens.data[1] : "default");
        } else if (!strcmp(key, "vt") || !strcmp(key, "vn") || !strcmp(key, "s") || !strcmp(key, "o") ||
                   !strcmp(key, "usemtl") || !strcmp(key, "mtllib"))
            ++out->ignored;
        else
            error = "unknown_keyword";
        if (error)
            out->errors[out->error_count++] = (InputError){out->lines, text(error)};
        free_lines(&tokens);
    }
    free(current);
    free_lines(&lines);
    return out;
}
void write_lines(const char *name, const Lines *lines) {
    char *path = format("output/%s", name);
    FILE *file = fopen(path, "wb");
    free(path);
    if (!file)
        return;
    for (int i = 0; i < lines->count; ++i) {
        fputs(lines->data[i], file);
        fputc('\n', file);
    }
    fclose(file);
}
void write_object(const Cleanup *clean, const Lines *groups) {
    Lines out = {0};
    line_push(&out, format("# vertices %d faces %d", clean->point_count, clean->faces.count));
    for (int v = 1; v <= clean->point_count; ++v)
        line_push(&out, format("v %s", point_text(clean->points[v])));
    int group = -1;
    for (int f = 0; f < clean->faces.count; ++f) {
        const Face *face = &clean->faces.data[f];
        if (face->group != group) {
            group = face->group;
            line_push(&out, format("g %s", groups->data[group]));
        }
        line_push(&out, format("f %d %d %d", face->v[0], face->v[1], face->v[2]));
    }
    write_lines("repaired.obj", &out);
    free_lines(&out);
}

#include "mesh.h"
bool directed(const Face *face, int a, int b) {
    for (int i = 0; i < 3; ++i)
        if (face->v[i] == a && face->v[(i + 1) % 3] == b)
            return true;
    return false;
}
void flip(Face *face) {
    int temporary = face->v[1];
    face->v[1] = face->v[2];
    face->v[2] = temporary;
}
void orient_faces(Faces *faces, const Topology *topology) {
    bool *visited = calloc((size_t)faces->count, sizeof(bool));
    for (int first = 0; first < faces->count; ++first)
        if (!visited[first]) {
            IntList queue = {0};
            int_push(&queue, first);
            visited[first] = true;
            for (int position = 0; position < queue.count; ++position) {
                int f = queue.data[position];
                Face face = faces->data[f];
                for (int i = 0; i < 3; ++i) {
                    int a = face.v[i], b = face.v[(i + 1) % 3];
                    const Edge *edge = &topology->edges[edge_index(topology, a, b)];
                    if (edge->faces.count != 2)
                        continue;
                    int other = edge->faces.data[0] == f ? edge->faces.data[1] : edge->faces.data[0];
                    if (visited[other])
                        continue;
                    if (directed(&faces->data[other], a, b))
                        flip(&faces->data[other]);
                    visited[other] = true;
                    int_push(&queue, other);
                }
            }
            int_free(&queue);
        }
    free(visited);
}
IntList inconsistent_edges(const Faces *faces, const Topology *topology) {
    IntList out = {0};
    for (int e = 0; e < topology->edge_count; ++e) {
        const Edge *edge = &topology->edges[e];
        if (edge->faces.count == 2 && directed(&faces->data[edge->faces.data[0]], edge->a, edge->b) ==
                                          directed(&faces->data[edge->faces.data[1]], edge->a, edge->b))
            int_push(&out, e);
    }
    return out;
}

#include "mesh.h"
void face_push(Faces *faces, Face face) {
    if (faces->count == faces->capacity) {
        faces->capacity = faces->capacity ? 2 * faces->capacity : 16;
        faces->data = resize(faces->data, (size_t)faces->capacity * sizeof(Face));
    }
    faces->data[faces->count++] = face;
}
Faces triangulate(const Object *object) {
    Faces out = {0};
    for (int p = 0; p < object->polygon_count; ++p) {
        const Polygon *polygon = &object->polygons[p];
        for (int i = 1; i + 1 < polygon->vertices.count; ++i) {
            Face face = {
                {polygon->vertices.data[0], polygon->vertices.data[i], polygon->vertices.data[i + 1]},
                p + 1,
                polygon->line,
                polygon->group,
                out.count + 1};
            face_push(&out, face);
        }
    }
    return out;
}
static Integer floor_div(Integer a, Integer b) {
    Integer quotient = a / b;
    if (a % b < 0)
        --quotient;
    return quotient;
}
Cleanup *cleanup(const Object *object, const Options *options) {
    Cleanup *out = calloc(1, sizeof(Cleanup));
    for (int v = 1; v <= object->vertex_count; ++v) {
        out->snapped[v] = object->vertices[v];
        bool changed = false;
        for (int axis = 0; axis < 3; ++axis) {
            Integer old = out->snapped[v].v[axis],
                    value = options->snap * floor_div(2 * old + options->snap, 2 * options->snap);
            out->snapped[v].v[axis] = value;
            if (value != old)
                changed = true;
        }
        out->snapped_count += changed;
        out->representative[v] = v;
        if (options->merge)
            for (int earlier = 1; earlier < v; ++earlier)
                if (!memcmp(&out->snapped[earlier], &out->snapped[v], sizeof(Point))) {
                    out->representative[v] = earlier;
                    break;
                }
        out->merged_count += out->representative[v] != v;
    }
    Faces triangles = triangulate(object);
    out->triangles = triangles.count;
    bool used[1001] = {0};
    for (int i = 0; i < triangles.count; ++i) {
        Face face = triangles.data[i];
        for (int j = 0; j < 3; ++j)
            face.v[j] = out->representative[face.v[j]];
        const char *reason = NULL;
        if (face.v[0] == face.v[1] || face.v[1] == face.v[2] || face.v[2] == face.v[0])
            reason = "repeated";
        else {
            Point n = normal(&face, out->snapped);
            if (options->degenerate && n.v[0] == 0 && n.v[1] == 0 && n.v[2] == 0)
                reason = "zero_area";
            else if (options->duplicates)
                for (int earlier = 0; earlier < out->faces.count; ++earlier) {
                    const Face *previous = &out->faces.data[earlier];
                    bool equal = true;
                    for (int j = 0; j < 3; ++j)
                        if (face.v[j] != previous->v[0] && face.v[j] != previous->v[1] &&
                            face.v[j] != previous->v[2])
                            equal = false;
                    if (equal) {
                        reason = "duplicate";
                        break;
                    }
                }
        }
        if (reason)
            out->removed[out->removed_count++] = (Removed){face.triangle, face.polygon, face.line, reason};
        else {
            for (int j = 0; j < 3; ++j)
                used[face.v[j]] = true;
            face_push(&out->faces, face);
        }
    }
    free(triangles.data);
    for (int v = 1; v <= object->vertex_count; ++v)
        if ((options->keep_unused && out->representative[v] == v) || (!options->keep_unused && used[v])) {
            out->new_number[v] = ++out->point_count;
            out->points[out->point_count] = out->snapped[v];
        }
    for (int f = 0; f < out->faces.count; ++f)
        for (int i = 0; i < 3; ++i)
            out->faces.data[f].v[i] = out->new_number[out->faces.data[f].v[i]];
    return out;
}
void fill_faces(Faces *faces, const Loop *loop, int group) {
    for (int i = 1; i + 1 < loop->vertices.count; ++i) {
        Face face = {
            {loop->vertices.data[0], loop->vertices.data[i + 1], loop->vertices.data[i]}, 0, 0, group, 0};
        face_push(faces, face);
    }
}

#include "mesh.h"
typedef struct {
    int a, b, face;
} Occurrence;
static int occurrence_compare(const void *left, const void *right) {
    const Occurrence *a = left, *b = right;
    if (a->a != b->a)
        return (a->a > b->a) - (a->a < b->a);
    if (a->b != b->b)
        return (a->b > b->b) - (a->b < b->b);
    return (a->face > b->face) - (a->face < b->face);
}
int edge_index(const Topology *topology, int a, int b) {
    if (a > b) {
        int temporary = a;
        a = b;
        b = temporary;
    }
    int low = 0, high = topology->edge_count;
    while (low < high) {
        int middle = low + (high - low) / 2;
        const Edge *edge = &topology->edges[middle];
        if (edge->a < a || (edge->a == a && edge->b < b))
            low = middle + 1;
        else
            high = middle;
    }
    return low < topology->edge_count && topology->edges[low].a == a && topology->edges[low].b == b ? low
                                                                                                    : -1;
}
Topology analyze(const Faces *faces, int vertices) {
    Topology out = {.vertices = vertices, .face_count = faces->count};
    out.vertex_faces = calloc((size_t)vertices + 1, sizeof(IntList));
    out.vertex_edges = calloc((size_t)vertices + 1, sizeof(IntList));
    out.neighbors = calloc((size_t)vertices + 1, sizeof(IntList));
    out.fan_components = calloc((size_t)vertices + 1, sizeof(IntList));
    out.fans = calloc((size_t)vertices + 1, sizeof(int));
    out.face_component = resize(NULL, (size_t)faces->count * sizeof(int));
    Occurrence *occurrences = resize(NULL, (size_t)faces->count * 3 * sizeof(Occurrence));
    for (int f = 0; f < faces->count; ++f) {
        out.face_component[f] = -1;
        for (int i = 0; i < 3; ++i) {
            int a = faces->data[f].v[i], b = faces->data[f].v[(i + 1) % 3];
            int_push(&out.vertex_faces[a], f);
            occurrences[3 * f + i] = (Occurrence){a < b ? a : b, a < b ? b : a, f};
        }
    }
    qsort(occurrences, (size_t)faces->count * 3, sizeof(Occurrence), occurrence_compare);
    out.edges = calloc((size_t)faces->count * 3, sizeof(Edge));
    for (int i = 0; i < faces->count * 3; ++i) {
        Occurrence occurrence = occurrences[i];
        if (!out.edge_count || out.edges[out.edge_count - 1].a != occurrence.a ||
            out.edges[out.edge_count - 1].b != occurrence.b) {
            int e = out.edge_count++;
            out.edges[e].a = occurrence.a;
            out.edges[e].b = occurrence.b;
            int_push(&out.vertex_edges[occurrence.a], e);
            int_push(&out.vertex_edges[occurrence.b], e);
            int_push(&out.neighbors[occurrence.a], occurrence.b);
            int_push(&out.neighbors[occurrence.b], occurrence.a);
        }
        int_push(&out.edges[out.edge_count - 1].faces, occurrence.face);
    }
    free(occurrences);
    for (int v = 1; v <= vertices; ++v)
        int_sort(&out.neighbors[v]);
    out.component_faces = calloc((size_t)faces->count, sizeof(IntList));
    out.component_vertices = calloc((size_t)faces->count, sizeof(IntList));
    out.component_edges = calloc((size_t)faces->count, sizeof(IntList));
    out.component_nonmanifold_vertices = calloc((size_t)faces->count, sizeof(IntList));
    for (int first = 0; first < faces->count; ++first)
        if (out.face_component[first] < 0) {
            int component = out.component_count++;
            IntList *queue = &out.component_faces[component];
            int_push(queue, first);
            out.face_component[first] = component;
            for (int position = 0; position < queue->count; ++position) {
                const Face *face = &faces->data[queue->data[position]];
                for (int i = 0; i < 3; ++i) {
                    const Edge *edge = &out.edges[edge_index(&out, face->v[i], face->v[(i + 1) % 3])];
                    for (int j = 0; j < edge->faces.count; ++j) {
                        int next = edge->faces.data[j];
                        if (out.face_component[next] < 0) {
                            out.face_component[next] = component;
                            int_push(queue, next);
                        }
                    }
                }
            }
            int_sort(queue);
            bool *used = calloc((size_t)vertices + 1, sizeof(bool));
            for (int i = 0; i < queue->count; ++i)
                for (int j = 0; j < 3; ++j)
                    used[faces->data[queue->data[i]].v[j]] = true;
            for (int v = 1; v <= vertices; ++v)
                if (used[v])
                    int_push(&out.component_vertices[component], v);
            free(used);
        }
    for (int e = 0; e < out.edge_count; ++e)
        int_push(&out.component_edges[out.face_component[out.edges[e].faces.data[0]]], e);
    for (int vertex = 1; vertex <= vertices; ++vertex) {
        bool *visited = calloc((size_t)faces->count, sizeof(bool));
        int *per_component = calloc((size_t)out.component_count, sizeof(int));
        for (int i = 0; i < out.vertex_faces[vertex].count; ++i) {
            int first = out.vertex_faces[vertex].data[i];
            if (visited[first])
                continue;
            IntList queue = {0};
            int_push(&queue, first);
            visited[first] = true;
            for (int position = 0; position < queue.count; ++position)
                for (int j = 0; j < out.vertex_edges[vertex].count; ++j) {
                    const Edge *edge = &out.edges[out.vertex_edges[vertex].data[j]];
                    if (!int_contains(&edge->faces, queue.data[position]))
                        continue;
                    for (int k = 0; k < edge->faces.count; ++k) {
                        int next = edge->faces.data[k];
                        if (!visited[next]) {
                            visited[next] = true;
                            int_push(&queue, next);
                        }
                    }
                }
            ++out.fans[vertex];
            ++per_component[out.face_component[first]];
            int_free(&queue);
        }
        for (int c = 0; c < out.component_count; ++c) {
            if (per_component[c])
                int_push(&out.fan_components[vertex], c);
            if (per_component[c] >= 2)
                int_push(&out.component_nonmanifold_vertices[c], vertex);
        }
        free(visited);
        free(per_component);
    }
    return out;
}
void topology_free(Topology *topology) {
    for (int e = 0; e < topology->edge_count; ++e)
        int_free(&topology->edges[e].faces);
    for (int v = 0; v <= topology->vertices; ++v) {
        int_free(&topology->vertex_faces[v]);
        int_free(&topology->vertex_edges[v]);
        int_free(&topology->neighbors[v]);
        int_free(&topology->fan_components[v]);
    }
    for (int c = 0; c < topology->component_count; ++c) {
        int_free(&topology->component_faces[c]);
        int_free(&topology->component_vertices[c]);
        int_free(&topology->component_edges[c]);
        int_free(&topology->component_nonmanifold_vertices[c]);
    }
    free(topology->edges);
    free(topology->face_component);
    free(topology->fans);
    free(topology->component_faces);
    free(topology->component_vertices);
    free(topology->component_edges);
    free(topology->component_nonmanifold_vertices);
    free(topology->vertex_faces);
    free(topology->vertex_edges);
    free(topology->neighbors);
    free(topology->fan_components);
    *topology = (Topology){0};
}
int loop_length(const Loop *loop) {
    return loop->vertices.count - (loop->closed ? 0 : 1);
}
Loops trace_loops(const Topology *topology) {
    Loops loops = {0};
    bool *used = calloc((size_t)topology->edge_count, sizeof(bool));
    for (int component = 0; component < topology->component_count; ++component)
        for (int i = 0; i < topology->component_edges[component].count; ++i) {
            int first = topology->component_edges[component].data[i];
            const Edge *edge = &topology->edges[first];
            if (edge->faces.count != 1 || used[first])
                continue;
            used[first] = true;
            Loop loop = {.component = component, .kind = "open"};
            int_push(&loop.vertices, edge->a);
            int_push(&loop.vertices, edge->b);
            while (loop.vertices.data[loop.vertices.count - 1] != edge->a) {
                int x = loop.vertices.data[loop.vertices.count - 1], selected = -1, other = 0;
                for (int j = 0; j < topology->vertex_edges[x].count; ++j) {
                    int e = topology->vertex_edges[x].data[j];
                    const Edge *candidate = &topology->edges[e];
                    if (used[e] || candidate->faces.count != 1 ||
                        topology->face_component[candidate->faces.data[0]] != component)
                        continue;
                    int y = candidate->a == x ? candidate->b : candidate->a;
                    if (selected < 0 || y < other) {
                        selected = e;
                        other = y;
                    }
                }
                if (selected < 0)
                    break;
                used[selected] = true;
                int_push(&loop.vertices, other);
            }
            loop.closed = loop.vertices.data[loop.vertices.count - 1] == edge->a;
            if (loop.closed)
                --loop.vertices.count;
            if (loops.count == loops.capacity) {
                loops.capacity = loops.capacity ? 2 * loops.capacity : 8;
                loops.data = resize(loops.data, (size_t)loops.capacity * sizeof(Loop));
            }
            loops.data[loops.count++] = loop;
        }
    free(used);
    return loops;
}
void loops_free(Loops *loops) {
    for (int i = 0; i < loops->count; ++i)
        int_free(&loops->data[i].vertices);
    free(loops->data);
    *loops = (Loops){0};
}
